-- ============================================================================
-- Carga y Actualizacion de Alumnos Oficiales TecNM (Padron Consolidado)
-- Total de alumnos unicos procesados: 9745
-- ============================================================================
ON CONFLICT (matricula) DO UPDATE SET
    cuenta_a = COALESCE(EXCLUDED.cuenta_a, alumnos.cuenta_a),
    id_carrera = COALESCE(EXCLUDED.id_carrera, alumnos.id_carrera),
    carrera = CASE WHEN EXCLUDED.id_carrera IS NOT NULL THEN EXCLUDED.carrera ELSE alumnos.carrera END,
    semestre = EXCLUDED.semestre;
